"use strict";

var _utilities = require("../../../utilities");
var _SaveOrChooseFilter = require("../SaveOrChooseFilter.utils");
var reportFilters = [{
  id: '111',
  name: 'Cherry',
  canDelete: true,
  modeOwner: {
    name: 'a'
  }
}, {
  id: '123',
  name: 'Avacado',
  canDelete: true,
  modeOwner: {
    name: 'a'
  }
}, {
  id: '456',
  name: 'applesauce',
  canDelete: true,
  modeOwner: {
    name: 'a'
  }
}];
describe('SaveOrChooseFilter.utils', function () {
  describe('convertFiltersToFilterOptions', function () {
    it('return empty', function () {
      expect((0, _SaveOrChooseFilter.convertFiltersToFilterOptions)(null)).toEqual([]);
    });
    it('should return expected', function () {
      var resetOption = {
        canEdit: false,
        displayInApp: false,
        lable: 'List Results Report'
      };
      var expectedFilters = [{
        canEdit: false,
        displayInApp: false,
        lable: 'List Results Report'
      }, {
        displayInApp: undefined,
        hoverText: 'Report Owner: a',
        label: 'applesauce',
        showIcon: true,
        value: '456'
      }, {
        displayInApp: undefined,
        hoverText: 'Report Owner: a',
        label: 'Avacado',
        showIcon: true,
        value: '123'
      }, {
        displayInApp: undefined,
        hoverText: 'Report Owner: a',
        label: 'Cherry',
        showIcon: true,
        value: '111'
      }];
      expect((0, _SaveOrChooseFilter.convertFiltersToFilterOptions)(reportFilters, resetOption)).toEqual(expectedFilters);
    });
    it('should return reset option if filters undefined', function () {
      var resetOption = {
        canEdit: false,
        displayInApp: false,
        lable: 'List Results Report'
      };
      expect((0, _SaveOrChooseFilter.convertFiltersToFilterOptions)(undefined, resetOption)).toEqual([resetOption]);
    });
  });
  describe('generateChange', function () {
    var setSelectedFilter = jest.fn();
    var setMultipleFilters = jest.fn();
    var refetch = jest.fn();
    it('should generate a callback', function () {
      var filter = {
        id: 1,
        fields: [{
          name: 'test',
          values: ['test']
        }]
      };
      (0, _SaveOrChooseFilter.generateChange)({
        setSelectedFilter: setSelectedFilter,
        refetch: refetch,
        setMultipleFilters: setMultipleFilters
      })(filter);
      expect(setMultipleFilters).toBeCalledWith([{
        filter: 'test',
        value: ['test']
      }], true);
      expect(setSelectedFilter).toBeCalledWith(1);
    });
    it('should use defaultFilterState if no filters provided', function () {
      var defaultFilterState = [{
        name: 'filter',
        values: []
      }];
      (0, _SaveOrChooseFilter.generateChange)({
        defaultFilterState: defaultFilterState,
        refetch: refetch,
        setSelectedFilter: setSelectedFilter,
        setMultipleFilters: setMultipleFilters
      })(undefined);
      expect(setMultipleFilters).toBeCalledWith([{
        filter: defaultFilterState[0].name,
        value: defaultFilterState[0].values
      }], false);
      expect(setSelectedFilter).toBeCalledWith(null);
    });
    it('should return null if no filters provided and no defaultFilterState', function () {
      expect((0, _SaveOrChooseFilter.generateChange)({
        defaultFilterState: null,
        setSelectedFilter: setSelectedFilter,
        setMultipleFilters: setMultipleFilters
      })(undefined)).toEqual(undefined);
    });
    it('should keep booleans as strings', function () {
      var filter = {
        id: 1,
        fields: [{
          name: 'test',
          values: ['true']
        }]
      };
      (0, _SaveOrChooseFilter.generateChange)({
        refetch: refetch,
        setMultipleFilters: setMultipleFilters,
        setSelectedFilter: setSelectedFilter
      })(filter);
      expect(setMultipleFilters.mock.calls[1][0]).toEqual([{
        filter: 'test',
        value: ['true']
      }]);
      expect(setSelectedFilter.mock.calls[0][0]).toEqual(1);
    });
  });
  describe('generateOnChangeCallback', function () {
    var onChange = jest.fn();
    it('returns callback when value undefined', function () {
      (0, _SaveOrChooseFilter.generateOnChangeCallback)({
        onChange: onChange,
        reportFilters: reportFilters,
        value: undefined
      });
      expect(onChange).toBeCalled();
    });
    it('returns callback when reportFilters undefined', function () {
      (0, _SaveOrChooseFilter.generateOnChangeCallback)({
        onChange: onChange,
        reportFilters: undefined,
        value: '111'
      });
      expect(onChange).toBeCalled();
    });
    it('calls callback with chosenFilter', function () {
      (0, _SaveOrChooseFilter.generateOnChangeCallback)({
        onChange: onChange,
        reportFilters: reportFilters,
        value: '111'
      });
      expect(onChange).toBeCalledWith({
        canDelete: true,
        id: '111',
        modeOwner: {
          name: 'a'
        },
        name: 'Cherry'
      });
    });
  });
  describe('generateOnTrailingIconClickCallback', function () {
    it('returns callback', function () {
      expect((0, _SaveOrChooseFilter.generateOnTrailingIconClickCallback)({})).toBeInstanceOf(Function);
    });
    it('callback should call onChange', function () {
      var event = {
        stopPropagation: jest.fn()
      };
      var setFilterToEdit = jest.fn();
      var callback = (0, _SaveOrChooseFilter.generateOnTrailingIconClickCallback)({
        setFilterToEdit: setFilterToEdit
      });
      callback({
        label: 'a',
        value: '1'
      })(event);
      expect(setFilterToEdit).toHaveBeenCalledTimes(1);
    });
  });
  describe('getQueryOptions', function () {
    test('should query options to return context and variables', function () {
      expect((0, _SaveOrChooseFilter.getQueryOptions)()).toEqual({
        variables: {
          mode: {
            id: 'TG9jYXRpb246',
            mode: 'LOCATION'
          },
          reportTypes: []
        }
      });
    });
    test('should return options with given reportTypes', function () {
      expect((0, _SaveOrChooseFilter.getQueryOptions)(['COMPLETION']).variables.reportTypes).toEqual(['COMPLETION']);
    });
  });
  describe('doArrayValuesMatch', function () {
    test('should default', function () {
      expect((0, _SaveOrChooseFilter.doArrayValuesMatch)([], [1], true)).toEqual(false);
      expect((0, _SaveOrChooseFilter.doArrayValuesMatch)([{
        name: 'Ted Lasso',
        values: [1]
      }], [{
        name: 'Coach Beard',
        values: [2]
      }, {
        name: 'Roy Kent',
        values: [6]
      }], false)).toEqual(false);
    });
    test('should return if array values match', function () {
      var array1 = [{
        name: '1',
        values: []
      }, {
        name: _utilities.FILTER_NAMES.dateFilterRange,
        values: ['1588831200', '1588917599']
      }];
      var array2 = [{
        name: '1',
        values: []
      }, {
        name: _utilities.FILTER_NAMES.dateFilterRange,
        values: ['1588831200', '1588917599']
      }];
      var differentArray1 = [{
        name: '1',
        values: []
      }, {
        name: _utilities.FILTER_NAMES.dateFilterRange,
        values: ['1588831211', '1588917602']
      }];
      var differentArray2 = [{
        name: '1',
        values: []
      }, {
        name: _utilities.FILTER_NAMES.dateFilterRange,
        values: ['1588831200', '1588917599']
      }, {
        name: 'extra',
        values: [true]
      }];
      expect((0, _SaveOrChooseFilter.doArrayValuesMatch)(array1, array2)).toEqual(true);
      expect((0, _SaveOrChooseFilter.doArrayValuesMatch)(array1, differentArray1)).toEqual(false);
      expect((0, _SaveOrChooseFilter.doArrayValuesMatch)(array1, differentArray2)).toEqual(false);
    });
  });
  describe('getFormattedDefaultFilterState', function () {
    test('should return formatted array', function () {
      var obj = {
        assigneeIds: [],
        dateFilterRange: [1588831200, 1588917599],
        dateFilterOption: ['DATE_RANGE'],
        hasActiveListInstances: ['true'],
        listTemplateIds: [],
        locationGroupIds: [],
        locationIds: [{
          id: '21',
          label: 'Jump Street'
        }],
        referencedByIds: [],
        sortOrder: []
      };
      var expectedArray = [{
        name: _utilities.FILTER_NAMES.assigneeIds,
        values: []
      }, {
        name: _utilities.FILTER_NAMES.dateFilterRange,
        values: ['1588831200', '1588917599']
      }, {
        name: _utilities.FILTER_NAMES.dateFilterOption,
        values: ['DATE_RANGE']
      }, {
        name: _utilities.FILTER_NAMES.hasActiveListInstances,
        values: ['true']
      }, {
        name: _utilities.FILTER_NAMES.listTemplateIds,
        values: []
      }, {
        name: _utilities.FILTER_NAMES.locationGroupIds,
        values: []
      }, {
        name: _utilities.FILTER_NAMES.locationIds,
        values: ['{"id":"21","label":"Jump Street"}']
      }, {
        name: _utilities.FILTER_NAMES.referencedByIds,
        values: []
      }, {
        name: _utilities.FILTER_NAMES.sortOrder,
        values: []
      }];
      expect((0, _SaveOrChooseFilter.getFormattedDefaultFilterState)(obj)).toEqual(expectedArray);
    });
    test('should return itself if undefined', function () {
      var obj = undefined;
      expect((0, _SaveOrChooseFilter.getFormattedDefaultFilterState)(obj)).toEqual(obj);
    });
  });
  describe('getHasChanges', function () {
    var currentFilters = [{
      name: _utilities.FILTER_NAMES.assigneeIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.dateFilterOption,
      values: ['DATE_RANGE']
    }, {
      name: _utilities.FILTER_NAMES.dateFilterRange,
      values: ['1588831200', '1588917599']
    }, {
      name: _utilities.FILTER_NAMES.hasActiveListInstances,
      values: ['true']
    }, {
      name: _utilities.FILTER_NAMES.listTemplateIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.locationGroupIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.locationIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.referencedByIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.sortOrder,
      values: []
    }];
    var formattedDefaultFilterState = [{
      name: _utilities.FILTER_NAMES.assigneeIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.dateFilterRange,
      values: ['1588831200', '1588917599']
    }, {
      name: _utilities.FILTER_NAMES.dateFilterOption,
      values: ['DATE_RANGE']
    }, {
      name: _utilities.FILTER_NAMES.hasActiveListInstances,
      values: ['true']
    }, {
      name: _utilities.FILTER_NAMES.listTemplateIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.locationGroupIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.locationIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.referencedByIds,
      values: []
    }, {
      name: _utilities.FILTER_NAMES.sortOrder,
      values: []
    }];
    var repFilters = [{
      id: 'UmVwb3J0RmlsdGVyOjExZWE5YjlmY2NlOWExMzA5YWNkMDJhYjlkZDdhOGM5',
      fields: currentFilters
    }];
    test('should report no changes', function () {
      expect((0, _SaveOrChooseFilter.getHasChanges)({
        currentFilters: currentFilters,
        filterToResetTo: undefined,
        formattedDefaultFilterState: formattedDefaultFilterState,
        reportFilters: repFilters
      })).toEqual(false);
    });
    test('should report no changes formattedDefaultFilterState is undefined', function () {
      expect((0, _SaveOrChooseFilter.getHasChanges)({
        formattedDefaultFilterState: undefined
      })).toEqual(false);
    });
    test('should report no changes if reportFilters is undefined', function () {
      expect((0, _SaveOrChooseFilter.getHasChanges)({
        currentFilters: currentFilters,
        filterToResetTo: 'UmVwb3J0RmlsdGVyOjExZWE5YjlmY2NlOWExMzA5YWNkMDJhYjlkZDdhOGM5',
        formattedDefaultFilterState: formattedDefaultFilterState,
        reportFilters: undefined
      })).toEqual(false);
    });
    test('should not report changes if selecting same report', function () {
      expect((0, _SaveOrChooseFilter.getHasChanges)({
        currentFilters: currentFilters,
        filterToResetTo: 'UmVwb3J0RmlsdGVyOjExZWE5YjlmY2NlOWExMzA5YWNkMDJhYjlkZDdhOGM5',
        formattedDefaultFilterState: formattedDefaultFilterState,
        reportFilters: repFilters
      })).toEqual(false);
    });
    test('should not report changes if filter not found in report filters', function () {
      expect((0, _SaveOrChooseFilter.getHasChanges)({
        currentFilters: currentFilters,
        filterToResetTo: 'UmVwb3J0RmlsdGVyOjExZWE5YjlmY2NlOWExMzA5YWNkMDJhYjlkZDdhOGM5',
        formattedDefaultFilterState: formattedDefaultFilterState,
        reportFilters: [{
          id: 'someotherid'
        }]
      })).toEqual(false);
    });
  });
  describe('getCanUpdateSelectedFilter', function () {
    test('should return true if no filterToResetTo', function () {
      var filterToResetTo = '';
      expect((0, _SaveOrChooseFilter.getCanUpdateSelectedFilter)(filterToResetTo, reportFilters)).toEqual(true);
    });
    test('should return false if no reportFilters', function () {
      var filterToResetTo = '111';
      expect((0, _SaveOrChooseFilter.getCanUpdateSelectedFilter)(filterToResetTo, null)).toEqual(false);
    });
    test('should return true if filterToResetTo canDelete true', function () {
      var filterToResetTo = '111';
      expect((0, _SaveOrChooseFilter.getCanUpdateSelectedFilter)(filterToResetTo, null)).toEqual(false);
    });
    test('should return false if filterToResetTo canDelete false', function () {
      var filterToResetTo = '111';
      var reportFilters2 = [{
        id: '111',
        name: 'Cherry',
        canDelete: false,
        modeOwner: {
          name: 'a'
        }
      }];
      expect((0, _SaveOrChooseFilter.getCanUpdateSelectedFilter)(filterToResetTo, reportFilters2)).toEqual(false);
    });
  });
});